#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# Sets up the credentials the Release workflow needs to upload new versions
# to the Chrome Web Store (API V2). Run it from anywhere inside the repo:
#   ./store/setup-webstore-api.sh
# Values are remembered in .env.webstore (git-ignored) for re-runs.

cd "$(dirname "$0")/.."
ENV_FILE=".env.webstore"

TOTAL_STAGES=7

banner "Chrome Web Store API for GitHub Actions"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Google account: 2-Step Verification"
say "The Chrome Web Store API only works for accounts with 2-Step Verification on."
say "Use the same Google account that owns the extension in the Developer Dashboard."
open_url "https://myaccount.google.com/signinoptions/twosv"
step "If 2-Step Verification is off, turn it on."
pause "Press Enter when it's on."

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Developer Dashboard: publisher ID and extension ID"
open_url "https://chrome.google.com/webstore/devconsole/"
step "Open Settings (Configurações) in the left menu. Copy the Publisher ID."
ask CWS_PUBLISHER_ID "Paste the publisher ID:"
step "Open the extension, then the Package tab. Copy the 32-letter Item ID."
ask CWS_EXTENSION_ID "Paste the extension (item) ID:"
write_env CWS_PUBLISHER_ID "$CWS_PUBLISHER_ID"
write_env CWS_EXTENSION_ID "$CWS_EXTENSION_ID"
set_var CWS_PUBLISHER_ID "$CWS_PUBLISHER_ID"
set_var CWS_EXTENSION_ID "$CWS_EXTENSION_ID"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: project and API"
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project (any name, e.g. gmail-pr-threads-release) and select it."
pause "Press Enter when the project is created and selected."
open_url "https://console.cloud.google.com/apis/library/chromewebstore.googleapis.com"
step "Check the project picker shows the new project, then click Enable."
pause "Press Enter when the Chrome Web Store API is enabled."

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: OAuth consent screen"
open_url "https://console.cloud.google.com/auth/overview"
step "Click Get started (or Configure consent screen)."
step "App name: anything (e.g. gmail-pr-threads release). Support email: yours."
step "Audience: External. Contact email: yours. Agree and click Create."
step "Go to Audience and click Publish app, then confirm."
warn "Don't skip Publish app: while the app is in Testing, Google expires the"
warn "refresh token after 7 days and releases start failing."
note "No verification is needed: you are the only user. Google may show an"
note "'unverified app' warning when you authorize later; that's expected."
pause "Press Enter when the consent screen is created and published."

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Google Cloud: OAuth client"
open_url "https://console.cloud.google.com/auth/clients"
step "Click Create client. Application type: Web application."
step "Under Authorized redirect URIs, add exactly:"
say  "    https://developers.google.com/oauthplayground"
step "Click Create. Copy the Client ID and the Client secret."
ask CWS_CLIENT_ID "Paste the client ID:"
ask_secret CWS_CLIENT_SECRET "Paste the client secret (hidden):"
write_env CWS_CLIENT_ID "$CWS_CLIENT_ID"
write_env CWS_CLIENT_SECRET "$CWS_CLIENT_SECRET"
set_secret CWS_CLIENT_ID "$CWS_CLIENT_ID"
set_secret CWS_CLIENT_SECRET "$CWS_CLIENT_SECRET"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "OAuth Playground: refresh token"
open_url "https://developers.google.com/oauthplayground"
step "Click the gear icon (top right) and tick 'Use your own OAuth credentials'."
step "Paste the client ID and client secret from the previous stage."
step "In 'Input your own scopes' (left, Step 1), enter exactly:"
say  "    https://www.googleapis.com/auth/chromewebstore"
step "Click Authorize APIs and sign in with the account that owns the extension."
note "If Google warns the app is unverified: Advanced → Go to … (unsafe)."
step "Back in Step 2, click 'Exchange authorization code for tokens'."
step "Copy the Refresh token."
ask_secret CWS_REFRESH_TOKEN "Paste the refresh token (hidden):"
write_env CWS_REFRESH_TOKEN "$CWS_REFRESH_TOKEN"
set_secret CWS_REFRESH_TOKEN "$CWS_REFRESH_TOKEN"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Check the credentials"
say "Asking Google for an access token and the extension's store status…"
token_response=$(curl -sS https://oauth2.googleapis.com/token \
  --data-urlencode "client_id=${CWS_CLIENT_ID}" \
  --data-urlencode "client_secret=${CWS_CLIENT_SECRET}" \
  --data-urlencode "refresh_token=${CWS_REFRESH_TOKEN}" \
  --data-urlencode "grant_type=refresh_token" || true)
access_token=$(python3 -c 'import json,sys; print(json.load(sys.stdin).get("access_token",""))' <<<"$token_response" 2>/dev/null || true)
if [[ -z "$access_token" ]]; then
  warn "Google did not return an access token:"
  note "$token_response"
  SKIPPED+=("Fix the OAuth client or refresh token, then re-run this wizard")
else
  status=$(curl -sS -H "Authorization: Bearer ${access_token}" \
    "https://chromewebstore.googleapis.com/v2/publishers/${CWS_PUBLISHER_ID}/items/${CWS_EXTENSION_ID}:fetchStatus" || true)
  if python3 -c 'import json,sys; d=json.load(sys.stdin); sys.exit(0 if d.get("itemId") else 1)' <<<"$status" 2>/dev/null; then
    printf '  %s✓ credentials work%s\n' "$GREEN" "$RESET"
    note "$status"
  else
    warn "Got a token, but the store did not return the item:"
    note "$status"
    SKIPPED+=("Check the publisher ID and extension ID, then re-run this wizard")
  fi
fi
pause "Press Enter to finish."

finish
say "Next release: bump \"version\" in manifest.json, commit, then"
say "  git tag v<version> && git push origin main v<version>"
say "The Release workflow builds the zips, creates the GitHub release and"
say "submits the new version to the Chrome Web Store."
printf '\n'
